import {$,esc,state,onData,options,preview,compare,time} from './workbench.js';
import {slotIndex,atlasItem} from './atlas-core.js';
const section=document.createElement('section');section.className='card tool-form';section.id='atlas-panel';section.innerHTML=`<div class="card-heading"><div><h2>单孔数值外观图鉴 <span class="tag">公开图鉴导入</span></h2><p>每个孔位数值选一件代表图；保留完整原始组合，不生成组合外观。</p></div><a href="https://zhexing.emoyilab.com/gallery" target="_blank" rel="noopener noreferrer">数据来源 ↗</a></div><p id="atlas-summary" role="status">正在读取图鉴目录…</p><div class="tool-grid"><label>谪星<select id="atlas-skin"></select></label><label>星格<select id="atlas-slot"></select></label><label>数值下限<input id="atlas-min" type="number" min="0" placeholder="不限"></label><label>数值上限<input id="atlas-max" type="number" min="0" placeholder="不限"></label></div><p id="atlas-info" class="subtle-note"></p><div id="atlas-values" class="sample-grid atlas-values"></div><div class="tool-pagination"><button id="atlas-prev" class="button secondary">上一页</button><span id="atlas-page"></span><button id="atlas-next" class="button secondary">下一页</button></div><p class="subtle-note">代表图是官方整件商品截图，其他星格仍会影响外观。原图链接按需加载，失效时明确提示；不复制参考站自制缩略图。图鉴记录没有现价、库存或成交含义。</p>`;
$('#gallery-view').prepend(section);
const target=document.createElement('section');target.id='sim-atlas';target.className='card tool-form';target.innerHTML='<h2>目标数值外观预览</h2><p class="subtle-note">各格独立查图，不拼接成组合渲染。选择图鉴数值会填入上方该格的精确目标范围。</p><div id="sim-atlas-values" class="sample-grid"></div><p id="sim-atlas-status" role="status"></p>';$('#simulator-view').append(target);
let manifest=null,current=null,maps=[],page=1,visible=[],request=0,simRequest=0,lastSimType=null;const cache=new Map();
async function load(id){if(!cache.has(id))cache.set(id,fetch('./atlas/'+id+'.json').then(async response=>{if(!response.ok)throw Error('该谪星尚无导入图鉴');return response.json()}).catch(error=>{cache.delete(id);throw error}));return cache.get(id)}
function entry(){return state.catalog.find(item=>item.id===$('#atlas-skin').value)}
async function selectSkin(){if(!$('#atlas-skin').value)return;const token=++request;$('#atlas-info').textContent='正在加载真实图鉴…';$('#atlas-values').replaceChildren();try{const data=await load($('#atlas-skin').value);if(token!==request)return;current=data;maps=slotIndex(data.rows,entry().slotNames.length);options($('#atlas-slot'),entry().slotNames.map((name,i)=>({value:String(i),label:name})));page=1;draw()}catch(error){if(token===request){current=null;$('#atlas-info').textContent=error.message;$('#atlas-page').textContent='';$('#atlas-prev').disabled=$('#atlas-next').disabled=true}}}
function imageError(image){image.hidden=true;const message=document.createElement('span');message.className='atlas-image-error';message.textContent='官方原图已失效或暂不可用';image.parentElement.append(message)}
function attachImages(host){host.querySelectorAll('img').forEach(image=>{image.onerror=()=>imageError(image)})}
function draw(){if(!current)return;const slot=Number($('#atlas-slot').value),map=maps[slot]??new Map(),min=$('#atlas-min').value,max=$('#atlas-max').value;if((min!==''&&!/^\d+$/.test(min))||(max!==''&&!/^\d+$/.test(max))||(min!==''&&max!==''&&Number(min)>Number(max))){$('#atlas-info').textContent='请输入有效数值范围，下限不能高于上限';$('#atlas-values').replaceChildren();return}
 const all=[...map.entries()].filter(([value])=>(min===''||value>=Number(min))&&(max===''||value<=Number(max))).sort((a,b)=>a[0]-b[0]),pages=Math.max(1,Math.ceil(all.length/12));page=Math.min(page,pages);visible=all.slice((page-1)*12,page*12);$('#atlas-info').textContent=`${entry().name} · ${entry().slotNames[slot]??'无星格'} · 已收录 ${map.size} 个数值，当前匹配 ${all.length} 个 · ${current.rows.length}条来源记录 · 导入 ${time(current.importedAt)}`;
 $('#atlas-values').innerHTML=visible.map(([value,row],i)=>`<article class="sample-card"><div class="sample-image"><img src="${esc(row.base+'/1.png')}" alt="${esc(entry().slotNames[slot])} ${value}代表外观" loading="lazy" referrerpolicy="no-referrer"></div><div><strong>${esc(entry().slotNames[slot])} · ${value}</strong><small>原始组合 ${esc(row.variation)}</small><small>第${slot+1}格品质标记 ${row.quality[slot]??'未知'}</small><button class="row-preview" data-atlas-preview="${i}">旋转预览</button><button class="row-preview" data-atlas-compare="${i}">加入比较</button></div></article>`).join('')||'<div class="empty">该范围暂无已收录单孔外观。</div>';
 $('#atlas-page').textContent=`${page} / ${pages}`;$('#atlas-prev').disabled=page<=1;$('#atlas-next').disabled=page>=pages;attachImages($('#atlas-values'));document.querySelectorAll('[data-atlas-preview]').forEach(button=>button.onclick=()=>preview(atlasItem(visible[Number(button.dataset.atlasPreview)][1],entry())));document.querySelectorAll('[data-atlas-compare]').forEach(button=>button.onclick=()=>{compare(atlasItem(visible[Number(button.dataset.atlasCompare)][1],entry()));button.textContent='已加入'})}
$('#atlas-skin').onchange=selectSkin;$('#atlas-slot').onchange=()=>{page=1;draw()};for(const id of ['min','max'])$('#atlas-'+id).oninput=()=>{page=1;draw()};$('#atlas-prev').onclick=()=>{page--;draw()};$('#atlas-next').onclick=()=>{page++;draw()};
async function sim(){if(document.body.dataset.page!=='simulator')return;const token=++simRequest,definition=state.catalog.find(item=>item.name===$('#sim-skin').value);if(!definition)return;$('#sim-atlas-values').replaceChildren();$('#sim-atlas-status').textContent='正在读取对应图鉴…';try{const data=await load(definition.id);if(token!==simRequest)return;if(lastSimType!==definition.id){lastSimType=definition.id;window.dispatchEvent(new CustomEvent('atlas-simulation-samples',{detail:data.rows.map(row=>atlasItem(row,definition,false))}))}const index=slotIndex(data.rows,definition.slotNames.length);$('#sim-atlas-values').innerHTML=definition.slotNames.map((name,i)=>`<article class="sample-card"><div class="tool-form"><label>${esc(name)}<select id="sim-atlas-select-${i}" aria-label="${esc(name)}图鉴数值"></select></label><div id="sim-atlas-image-${i}"></div></div></article>`).join('');
 for(let i=0;i<index.length;i++){const select=$('#sim-atlas-select-'+i),values=[...index[i].keys()].sort((a,b)=>a-b);options(select,values.map(value=>({value:String(value),label:String(value)})),'选择已收录数值');const chosen=$('#sim-min-'+i).value;if($('#sim-max-'+i).value===chosen&&index[i].has(Number(chosen))&&chosen!=='')select.value=chosen;
  const show=()=>{const row=select.value===''?null:index[i].get(Number(select.value)),host=$('#sim-atlas-image-'+i);host.replaceChildren();if(!row)return;const item=atlasItem(row,definition);host.innerHTML=`<div class="sample-image"><img src="${esc(item.thumbnail)}" alt="${esc(definition.slotNames[i])} ${select.value}代表图" referrerpolicy="no-referrer" loading="lazy"></div><small>完整来源组合 ${esc(row.variation)}</small><button class="row-preview">旋转检视来源图</button>`;host.querySelector('button').onclick=()=>preview(item);attachImages(host)};select.onchange=()=>{if(select.value!==''){for(const bound of ['min','max']){$('#sim-'+bound+'-'+i).value=select.value;$('#sim-'+bound+'-'+i).dispatchEvent(new Event('input',{bubbles:true}))}}show()};show();}
 $('#sim-atlas-status').textContent=definition.slotNames.length?'仅展示每格代表图；未收录值留空，其他星格与当前演练组合可能不同。':'该谪星无星格。';
 }catch(error){if(token===simRequest)$('#sim-atlas-status').textContent=error.message}}
$('#sim-skin').addEventListener('change',sim);window.addEventListener('simulate-skin',sim);for(const input of document.querySelectorAll('#simulator-view .tool-slot input'))input.addEventListener('change',sim);
onData(()=>{const id=$('#atlas-skin').value;options($('#atlas-skin'),state.catalog.map(item=>({value:item.id,label:item.name})));if(document.body.dataset.page==='gallery'&&(id!==$('#atlas-skin').value||!current))selectSkin();if(document.body.dataset.page==='simulator')sim()});
try{const response=await fetch('./atlas/index.json');if(!response.ok)throw Error('图鉴尚未导入');manifest=await response.json();$('#atlas-summary').textContent=`已导入 ${manifest.items.filter(item=>item.status==='ok').length}/${manifest.items.length} 种谪星 · ${manifest.items.reduce((n,item)=>n+(item.count??0),0).toLocaleString()} 条变体来源记录 · ${manifest.items.reduce((n,item)=>n+(item.slotCounts??[]).reduce((a,b)=>a+b,0),0).toLocaleString()} 个孔位数值索引 · ${time(manifest.importedAt)}`;}catch(error){$('#atlas-summary').textContent=error.message}

window.addEventListener('portal-route',e=>{if(e.detail==='gallery'&&(!current||current.equipType!==$('#atlas-skin').value))selectSkin();if(e.detail==='simulator')sim()});
window.addEventListener('portal-prefetch',e=>{if(!navigator.connection?.saveData&&['gallery','simulator'].includes(e.detail)){const id=e.detail==='gallery'?$('#atlas-skin').value:state.catalog.find(i=>i.name===$('#sim-skin').value)?.id;if(id)load(id).catch(()=>{})}});
